In particular, in the dense graph model, a graph $G$ is said to be $\epsilon$-far from the property $\Pi$ if at least $\epsilon n^2$ edges must be added or removed from $G$ to make it have the property.

\paragraph{Notations.}

Let $G=(V,E)$ be a graph.
Throughout we use $\deg(v)$ to denote the degree of $v$ in $G,$ and for $S \subseteq V$ we use $\deg_{G[S]}(v)$ to denote the degree of $v$ in $G[S].$
For $S,T \subseteq V$ use $E(S)$ to denote the set of edges in $G$ with both endpoints in $S,$ and use $E(S,T)$ to denote the set of edges in $G$ with one endpoint in $S$ and one endpoint in $T.$
We use the notation $S_{\uparrow v}$ to denote all vertices in $S$ with more neighbours in $S$ than $v.$
In other words, \[S_{\uparrow v} = \{u \in S : |N(u) \cap S| > |N(v) \cap S|\}.\]
We define the edge density of a subgraph $S \subseteq V$ as $\frac{|E(S)|}{\binom{|S|}{2}}.$
Throughout, we say \emph{subgraph} to refer to the \emph{induced subgraph} $G[S].$
We use $\log(\cdot)$ to denote $\log_2(\cdot).$
Finally, for a set $S$ we use $P(S)$ to denote the power set of $S.$

\begin{definition}
    \label{def:fingeprint}
    Let $U \subseteq V$ be a subset of vertices in a graph $G=(V,E)$.
    A \emph{fingerprint} on $U$ is a pair $(F,R)$ where $F$ is a sequence $(f_1,f_2,\dots,f_{|F|})$ where each $f_i \in U \times \{\uparrow,\downarrow\}$ and $R \in \left([|F|] \times U \right) \cup \{\bot\}.$
    $F$ is called the fingerprint sequence, and $R$ is called the revision.
    The $\bot$ is used to denote that there is no revision.
    We use $\mathcal{F}(U)$ to denote the set of all possible fingerprints on $U.$
\end{definition}

\begin{definition}
    \label{def:MRR}
    Given a graph $G=(V,E),$ subsets of vertices $J,C \subseteq V$ and parameters $\epsilon,\rho,\ell,$ define the \emph{maximum removal ratio}, denoted ${\rm MRR}_{G}(J,C),$ as \[ {\rm MRR}_{G}(J,C) \coloneqq \max_{v \in J} \max\left(\frac{\deg_{G[C \cup \{v\}]}(v)}{\max(\deg_{G[J]}(v),\frac{\epsilon}{\sqrt{\ell} \rho^2}|J|)},\frac{|C_{\uparrow v}|}{\max(|C_{\uparrow v} \cap J|,\frac{\epsilon}{\sqrt{\ell} \rho^2}|J|)}\right).\]
    While this quantity depends on $\epsilon,\rho$ and $\ell,$ we suppress this dependence in the notation ${\rm MRR}_G(J,C)$ for clarity.
\end{definition}

\begin{algorithm}
    \caption{\sc{Fingerprint Generator}}
    \label{alg:Fingerprint}
    \smallskip
    \KwIn{A graph $G=(V,E),$ and $J \subseteq V$ for which $G[J]$ has fewer than $\frac{\epsilon}{\ell \rho^2}|J|^2$ edges}
    \medskip
    Initialize $t=0, F \gets ()$ and $C_0 \gets V$\;

    \While{$G[C_t]$ has more than $\epsilon n^2/4$ edges} {
        $t \gets t+1$\;
        $v_t \gets$ $\argmax_{v \in J} \max\left(\frac{\deg_{G[C_{t-1} \cup \{v\}]}(v)}{\max(\deg_{G[J]}(v),\frac{\epsilon}{\sqrt{\ell} \rho^2}|J|)},\frac{|(C_{t-1})_{\uparrow v}|}{\max(|(C_{t-1})_{\uparrow v} \cap J|,\frac{\epsilon}{\sqrt{\ell} \rho^2}|J|)}\right)$\;
        \If{$v_t$ comes from the first type}{
            $C_t \gets C_{t-1} \setminus N(v_t)$\;
            Append $(v_t,\downarrow)$ to $F$\;
        }
        \Else{
            $C_t \gets C_{t-1} \setminus (C_{t-1})_{\uparrow v_t}$\;
            Append $(v_t,\uparrow)$ to $F$\;
        }
    }
    Return $F$\;
\end{algorithm}

\begin{algorithm}
    \caption{\sc{Container Generator}}
    \label{alg:Container}
    \smallskip
    \KwIn{A graph $G=(V,E),$ and fingerprint sequence $F$ and revision $R$}
    \medskip
    Initialize $C_0 \gets V$\;

    \For{$t=1,2,\dots,|F|$} {
        \If{$F[t]=(v,\downarrow),$ for some $v \in V$}{$C_t \gets C_{t-1} \setminus N(v)$}
        \Else{$C_t \gets C_{t-1} \setminus (C_{t-1})_{\uparrow v}$}
    }

    \If{$R=(i,u)$} {
        Return $C_{|F|} \setminus (C_i)_{\uparrow u}$
    }
    \Else{
        Return $C_{|F|}$\;
    }
\end{algorithm}

\begin{lemma}
    \label{lem:degreeThresholdExistence}
    Let $G=(V,E)$ be a graph and let $U,W \subseteq V.$
    If $|E(U,W)| \geq m_{UW}$ then there exists $\frac{m_{UW}}{2|U|} \leq d \leq |W|$ such that the number of vertices in $U$ with more than $d$ neighbours in $W$ is at least \[\frac{m_{UW}}{4d \log(2|U||W|/m_{UW})}.\]
\end{lemma}


